package com.example.praticum.ui.evaluation;
import android.view.*;import android.widget.PopupMenu;import android.widget.TextView;import androidx.annotation.*;import androidx.recyclerview.widget.RecyclerView;import com.example.praticum.R;import com.example.praticum.data.entity.Evaluation;import com.google.android.material.button.MaterialButton;import java.text.*;import java.util.*;
public final class EvaluationHistoryAdapter extends RecyclerView.Adapter<EvaluationHistoryAdapter.Holder>{
 public interface Listener{void onConsult(Evaluation e);void onEdit(Evaluation e);void onDelete(Evaluation e);}private final List<Item> items=new ArrayList<>();private final Listener listener;public EvaluationHistoryAdapter(Listener l){listener=l;}public void submitList(List<Item>x){items.clear();if(x!=null)items.addAll(x);notifyDataSetChanged();}
 @NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_evaluation_record,p,false));}
 public void onBindViewHolder(@NonNull Holder h,int p){Item x=items.get(p);Evaluation e=x.evaluation;h.title.setText("Évaluation n° "+e.getId());String date=e.getFinalizedAt()==null?"Enregistrée":new SimpleDateFormat("dd/MM/yyyy · HH:mm",Locale.getDefault()).format(new Date(e.getFinalizedAt()));h.meta.setText(date+" · "+x.studentCount+(x.studentCount==1?" étudiant":" étudiants"));h.average.setText(x.studentCount==0?"— / 20":String.format(Locale.getDefault(),"Moyenne · %.2f / 20",x.average));h.itemView.setOnClickListener(v->listener.onConsult(e));h.actions.setOnClickListener(v->{PopupMenu m=new PopupMenu(v.getContext(),h.actions);m.getMenu().add("Modifier").setOnMenuItemClickListener(i->{listener.onEdit(e);return true;});m.getMenu().add("Supprimer").setOnMenuItemClickListener(i->{listener.onDelete(e);return true;});m.show();});}
 public int getItemCount(){return items.size();}static final class Item{final Evaluation evaluation;final int studentCount;final double average;Item(Evaluation e,int n,double a){evaluation=e;studentCount=n;average=a;}}
 static final class Holder extends RecyclerView.ViewHolder{final TextView title,meta,average;final MaterialButton actions;Holder(View v){super(v);title=v.findViewById(R.id.tvEvaluationRecordTitle);meta=v.findViewById(R.id.tvEvaluationRecordMeta);average=v.findViewById(R.id.tvEvaluationRecordAverage);actions=v.findViewById(R.id.btnEvaluationRecordActions);}}
}